(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["it"] = {"ui":{"skip":"Vai al contenuto","back":"← Torna ad AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Scegli una lingua","lang.search":"Cerca lingue","lang.none":"Nessuna lingua corrisponde","lang.notYet":"{name} non è ancora tradotto","theme.aria":"Cambia tema: chiaro, scuro o nero","theme.toLight":"Passa al tema chiaro","theme.toDark":"Passa al tema scuro","theme.toBlack":"Passa al tema nero (nero vero, riposante sugli schermi OLED)","words.underline":"Sottolinea queste parole nella pagina","words.underlineHelp":"Passa il mouse o tocca una parola sottolineata a puntini per vedere cosa significa.","words.col.todo":"Le schede scelte per ora: il team parte da queste.","words.col.doing":"Un'IA sta lavorando su questa scheda in questo momento.","words.col.review":"Un'IA ha finito il lavoro; un'altra lo controlla prima che arrivi a te.","words.col.verify":"Si aspetta te: provalo e dì se funziona.","words.col.team":"I tuoi appunti o le tue risposte, in attesa che il team li prenda in carico.","words.col.done":"Finito e accettato.","index.title":"AI-gile: il tuo team di sviluppo AI, su una sola board","index.description":"AI-gile è una board kanban per team di programmazione AI. Lavorano mentre dormi; tu trovi un'unica pila corta di cose da decidere, provare e accettare.","hero.logoAlt":"Icona della board AI-gile","hero.h1.html":"Il tuo team di sviluppo AI, su una sola&nbsp;board.","hero.alpha":"🐣 Pre-alpha chiusa","hero.alphaTitle":"Ancora acerba e incompleta: grazie di provarla!","hero.lede":"Costruiscono mentre dormi. Ti svegli con un'unica pila corta: qualche domanda, qualche cosa da provare, un rombo viola o due. Clic, accetta, e torni al tuo caffè.","dl.windows":"App per Windows","dl.browser":"Usala nel browser","dl.messenger":"📱 Messenger per il tuo telefono","dl.soon":"In arrivo","dl.notify":"🔔 Avvisami quando apre","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, ma il team non ha mai bisogno del caffè in piedi della riunione. (Le riunioni in piedi le fa lo stesso.)","pitch.h2":"AI-gile in quante parole vuoi","pitch.lede":"Scegli una lunghezza, da una parola a 144. Ogni lunghezza è una descrizione a sé, scritta per quella misura. Trascina il cursore o usa le frecce.","pitch.rangeLabel":"Lunghezza in parole","pitch.dice":"🎲 un'altra versione","pitch.words.one":"{n} parola","pitch.words.other":"{n} parole","pitch.letters.one":"{n} lettera","pitch.letters.other":"{n} lettere","pitch.chars.one":"{n} carattere","pitch.chars.other":"{n} caratteri","count.line.html.one":"{n} card sulla board in questo momento","count.line.html.other":"{n} card sulla board in questo momento","people.humans.html.one":"👥 {n} umano","people.humans.html.other":"👥 {n} umani","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agenti","people.working.html.one":"⚡ {n} al lavoro in questo momento","people.working.html.other":"⚡ {n} al lavoro in questo momento","pre.title":"AI-gile: qui si sta costruendo qualcosa","pre.description":"Qui si sta costruendo qualcosa. Una board dove team di AI costruiscono quello che chiedi, e intanto ti insegnano. Per ora, pre-alpha chiusa tra amici.","pre.h1":"Qui si sta costruendo qualcosa. 🤫","pre.line":"Una board dove team di AI costruiscono quello che chiedi, e intanto ti insegnano. Per ora, pre-alpha chiusa tra amici.","pre.btn":"🔔 Avvisami quando apre","pre.peek":"Dietro il vetro: la board vera, dal vivo. Ogni scheda è una barra colorata.","pre.peekFake":"Dietro il vetro: ecco com'è una board al lavoro.","pre.night":"🌙 Il guardiano notturno è al comando · 😴 l'umano riposa","features.aria":"Cosa fa","f.pile.h":"Una sola pila per te","f.pile.html":"<b>Per te</b> raccoglie tutto ciò che aspetta te, da ogni progetto: domande, cose da provare, compiti che solo una persona può fare. La tua coda dice cosa viene dopo e quanto ci vuole.","f.sleep.h":"Team che lavorano mentre dormi","f.sleep.p":"Ogni progetto ha un lead e un team di agenti AI. Commenta una card e il team si sveglia, fa il lavoro e te lo restituisce con passaggi che anche una persona stanca può seguire.","f.tester.h":"Prima controlla un tester AI","f.tester.p":"Prima che arrivi qualcosa a te, un tester segue i passaggi in una copia dell'app e mostra cosa ha visto, con uno screenshot. Scorri quelli superati e accetta con un clic.","f.proof.h":"Prove, non promesse","f.proof.p":"Ogni consegna mostra cosa è cambiato: i file, il diff, gli screenshot. Niente più apri-ogni-app-per-vedere-se-è-finito.","f.chat.h":"Chatta con i tuoi lead","f.chat.p":"Una barra stile Discord: un'icona per progetto, rombi viola per ciò che ha bisogno di te. Scrivi un'idea a un lead; la trasforma in card e in un piano, con un pulsante ✅ Vai.","f.tidy.h":"Si tiene in ordine da sola","f.tidy.p":"Le card affini si fondono in una, i titoli confusi vengono sistemati e un controllo dei token tiene il codice snello. Meno cose tra cui passare, meno a cui pensare.","f.private.h":"Tua, sul tuo computer","f.private.li1":"La board gira sulla tua macchina e risponde solo a te.","f.private.li2":"I messaggi privati tra persone sono cifrati end-to-end.","f.private.li3":"Nessun account, nessun tracker, nessun cookie.","f.lang.h":"Nella tua lingua","f.lang.p":"Oltre 120 lingue, dall'olandese, al gallese e al giapponese fino al pirata, a Yoda e al klingon, con un cambio rapido all'inglese per il gergo tecnico.","f.service.h":"Da un'idea a un vero servizio","f.service.p":"Hai costruito con l'AI qualcosa che ora le persone usano? Segnalo come servizio e la board ti aiuta a gestirlo bene: controlli di uptime, una pagina di stato pubblica, incidenti con un resoconto, modifiche che richiedono un Vai, backup controllati ogni giorno. L'Aiuto ti spiega ogni passaggio man mano.","msgr.h2":"AI-gile Messenger: il tuo team in tasca","msgr.p1":"Parla con il tuo team IA senza aprire la board. Chatta con i lead dei tuoi progetti e con i tuoi amici, guarda i passaggi di test di una card e rispondi, tutto dal telefono.","msgr.p2":"Per collegarlo, scansiona un codice QR sulla tua board. Prima volta? Una chat demo amichevole ti fa fare un giro.","msgr.when":"Prima Android, poi una versione web per telefoni e iPhone.","msgr.who":"Il lead del tuo progetto","msgr.b1":"La correzione della modalità scura è pronta. Vuoi i passaggi di test?","msgr.b2":"Sì, grazie!","msgr.b3":"1. Apri Impostazioni. 2. Scegli Scuro. Ti sembra a posto?","tl.aria":"Cronologia dalla prima conversazione alla roadmap","tl.h2":"Dalla prima chiacchierata a ciò che verrà","tl.lede":"Date e orari veri, nel tuo fuso orario. Da oggi in poi è il piano, senza date promesse.","tl.today":"Oggi","tl.planned":"previsto","tl.doing":"in corso","tl.cards.one":"{n} card","tl.cards.other":"{n} card","join.h2":"Unisciti","join.lede":"AI-gile lo sta costruendo un barbuto un po' strambo, con l'AuDHD e qualche battaglia con la salute mentale, insieme a un gran numero di agenti pazienti. Per ora è privato, in un'alpha chiusa con gli amici. Vuoi provarlo quando si apre?","join.btn":"Registra il tuo interesse","join.small":"Ti scriveremo una mail, nient'altro","footer.tag":"AI-gile. Niente tracker, niente cookie, niente caffè in piedi.","footer.licence":"Licenza aziendale","footer.status":"Stato","footer.privacy":"Cosa conserviamo","footer.thanks":"Chiamate grazie a ChilledChat","form.sending":"Invio…","form.failed":"Non ha funzionato: riprova più tardi.","form.offline":"Non riesco a raggiungere AI-gile: riprova più tardi.","form.keep":"Lo usiamo solo per risponderti, poi lo cancelliamo. Niente tracker, niente cookie.","form.keepLink":"Cosa conserviamo","interest.title":"AI-gile: avvisami quando apre l'alpha","interest.description":"Lascia la tua email per sapere quando apre l'alpha o la beta chiusa di AI-gile.","interest.h1":"🔔 Avvisami quando apre","interest.lede":"AI-gile è in pre-alpha chiusa. Lascia la tua email e ti scriviamo una sola volta, quando c'è un posto per te.","interest.email":"La tua email","interest.which":"Quale test?","interest.alpha":"Alpha chiusa: presto, ruvida, molti cambiamenti","interest.beta":"Beta: più stabile, più avanti","interest.both":"Una qualsiasi, la prima che arriva","interest.submit":"Mettimi in lista","interest.thanks":"Grazie! Sei in lista.","licence.title":"AI-gile: licenza aziendale","licence.description":"Usi AI-gile nella tua attività? Richiedi una licenza aziendale gratuita.","licence.h1":"📜 Licenza aziendale","licence.lede":"Usi AI-gile al lavoro? Raccontaci chi sei e cosa fai. Se fa del bene, la licenza è gratuita.","licence.company":"Azienda","licence.website":"Sito web","licence.what":"Di cosa ti occupi","licence.how":"Come aiuta il mondo","licence.email":"Email","licence.submit":"Invia richiesta","licence.thanks":"Grazie! Ti rispondiamo via email.","status.title":"Stato di AI-gile","status.h1":"Stato di AI-gile","status.quiet":"Tutto tranquillo","status.intro":"AI-gile funziona in questo momento? Questa pagina controlla il sito, la condivisione delle board, le chiamate e il download ogni 5 minuti.","status.up":"Funziona (ha risposto in {ms} ms)","status.slow":"Non ha risposto all'ultimo controllo, riprovo","status.down":"Non funziona: non ha risposto agli ultimi due controlli","status.svc.web":"Sito web","status.svc.web.offers":"Questo sito: cos'è AI-gile e il modulo di interesse","status.svc.boards":"Condivisione delle board","status.svc.boards.offers":"Board pubbliche, messaggi tra amici e inviti","status.svc.calls":"Chiamate","status.svc.calls.offers":"Voce, video e condivisione schermo in AI-gile","status.svc.download":"Download","status.svc.download.offers":"Il programma di installazione per Windows e i link di invito","status.checking":"Controllo…","status.offline":"Al momento non riesco a raggiungere il servizio di stato (riprovo)","status.updated":"aggiornato {ago}","status.justNow":"proprio ora","status.min":"{n} min fa","status.hours":"{n} h fa","status.days":"{n} g fa","privacy.title":"AI-gile: cosa conserviamo","privacy.h1":"Cosa conserviamo","privacy.lede":"In breve: solo quello che ci mandi, e non a lungo.","privacy.only":"Solo quello che ci mandi: quello che scrivi in un modulo, come la tua email. Nient'altro su di te.","privacy.sealed":"È sigillato, così il nostro server non può leggerlo: nel tuo browser, prima che parta (su un browser più vecchio, nel momento in cui arriva). Solo la nostra board può aprirlo.","privacy.server":"Viene cancellato dal server appena raggiunge la nostra board. Quello che resta lì dopo 30 giorni viene cancellato comunque.","privacy.board":"Lo teniamo sulla nostra board solo finché non ti abbiamo risposto, poi lo cancelliamo anche lì.","privacy.none":"Niente tracker, niente cookie, niente statistiche.","privacy.local":"La lingua e la scelta tra chiaro e scuro restano nel tuo browser. Non ci vengono mai inviate.","privacy.ask":"Vuoi che sparisca prima? Rispondi alla nostra email e diccelo.","live.h2":"Guardalo mentre prende forma, dal vivo","live.caption":"Ogni scheda è nascosta: vedi la forma del lavoro, non le parole.","live.watching.one":"dal vivo: {n} spettatore","live.watching.other":"dal vivo: {n} spettatori","live.last.now":"Ultima scheda spostata proprio ora","live.last.min.one":"Ultima scheda spostata {n} minuto fa","live.last.min.other":"Ultima scheda spostata {n} minuti fa","live.last.hour.one":"Ultima scheda spostata {n} ora fa","live.last.hour.other":"Ultima scheda spostata {n} ore fa","live.last.day.one":"Ultima scheda spostata {n} giorno fa","live.last.day.other":"Ultima scheda spostata {n} giorni fa","live.offline":"La bacheca dal vivo si prende una pausa. Torna presto.","live.cols":"Backlog|Da fare|In corso|Il team controlla|Per te da testare|Per il team|Fatto"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Delegato."]},{"n":2,"texts":["Kanban robotico.","Agenti, organizzati.","Idee, realizzate."]},{"n":3,"texts":["Kanban per robot.","Le idee diventano funzioni.","Kanban gratuito, con agenti."]},{"n":5,"texts":["Una board kanban gestita da agenti.","Tu scrivi card. Loro costruiscono.","Gratis, locale, testato, un po' buffo."]},{"n":8,"texts":["Una board kanban gratuita dove lavorano agenti AI.","Scrivi un'idea. Gli agenti la costruiscono. Tu accetti.","Agile per un essere umano e tanti robot pazienti."]},{"n":13,"texts":["Una board kanban sul tuo computer, dove gli agenti AI prendono in carico le card.","Scrivi un'idea. Un team di agenti la costruisce. Un tester la controlla prima di te.","Gratis, senza account né tracker: una board, qualche robot e il comando a te."]},{"n":21,"texts":["AI-gile è una board kanban per lavorare con agenti AI che programmano. Loro prendono in carico le card; tu le provi e le accetti.","Ogni progetto ha un lead e un team di agenti AI. Commenta una qualsiasi card e il team si mette al lavoro.","Una board personale e gratuita che gira sul tuo computer. A lavorare sono i robot. A dire di sì sei tu."]},{"n":34,"texts":["Metti le idee su una board. Un team di agenti AI le trasforma in funzioni che funzionano, le testa e te le riporta con i passaggi per provarle. Niente conta come finito finché non lo dici tu.","AI-gile è una board kanban fatta in casa, che Rich ha costruito con un grande aiuto dagli agenti che ora gestisce. È gratuita, gira sul tuo computer e si condivide con gli amici, non si vende.","Immagina una normale board kanban, con colonne dal Backlog a Fatto, solo che le card le prendono in carico agenti AI. Riferiscono i progressi, fanno domande quando sono bloccati e aspettano sempre il tuo via libera."]},{"n":55,"texts":["AI-gile è una board kanban in cui il team è fatto di agenti AI. Ogni progetto ha un lead che pianifica il lavoro e dei collaboratori che lo costruiscono. Quando una funzione è pronta, un tester AI la prova e fa uno screenshot, poi arriva nella tua pila. Accettala, oppure commenta e la rifanno.","È nata come il modo di una persona per tenere d'occhio tante sessioni di programmazione con l'AI insieme, ed è diventata una vera board. Gira sulla tua macchina, non vuole account e non ha tracker. È gratis per gli amici e per i curiosi. È anche incompleta, quindi aspettati qualche spigolo e ogni tanto una sorpresa.","Ecco la versione onesta. Le idee devi averle tu, e i risultati devi controllarli tu. Quello che fa AI-gile è tutto ciò che sta in mezzo: tiene le card in ordine, sveglia l'agente giusto quando commenti, mostra esattamente cosa è cambiato e raccoglie tutto in un'unica pila corta per te."]},{"n":89,"texts":["AI-gile è una board kanban gratuita che fai girare sul tuo computer. Invece delle persone, ogni progetto ha un team di agenti AI: un lead che trasforma le tue idee in card e in un piano, e dei collaboratori che prendono le card in ordine di priorità. Quando qualcosa è costruito, un tester AI segue i passaggi di prova e ti mostra cosa ha visto. Poi aspetta in un'unica pila chiamata Per te. Tu lo accetti, oppure commenti e il team riprova. Niente arriva mai in Fatto senza di te.","Qualche funzione che forse non ti aspetti. Una guardia notturna tiene piena la colonna Da fare mentre dormi, scegliendo card che non richiedono una tua risposta. Un contatore di token mostra quanto hanno usato gli agenti oggi e in questa settimana, e la modalità No Token Mode dice loro di smettere di spendere. Puoi scrivere agli amici, e i messaggi privati sono cifrati end-to-end. La board parla circa 120 lingue, tra cui olandese, fiammingo, pirata e klingon. Niente di tutto questo costa un centesimo, e nessuno cerca di vendertelo.","AI-gile è un piccolo progetto personale, non un'azienda. Rich voleva seguire diversi progetti di programmazione con l'AI senza aprire ogni app per controllarli, così lui e gli agenti hanno costruito una board per farlo, e poi l'hanno usata per costruire il resto di se stessa. È in pre-alpha chiusa, il che significa che funziona, più o meno, per una manciata di amici. Non c'è una pagina dei prezzi, né una newsletter, né un piano di crescita. Se ti sembra utile, puoi chiedere di provarla quando si aprirà un po' di più."]},{"n":144,"texts":["AI-gile è una board kanban per un essere umano e un sacco di agenti AI. Gira sul tuo computer ed è completamente gratuita. Aggiungi dei progetti, e ogni progetto riceve un lead e un piccolo team. Chatti con il lead, un po' come su Discord, e descrivi un'idea; il lead la trasforma in card e in un piano, poi aspetta che premi Vai. Il team lavora le card in ordine di priorità, usando una semplice riga di comando pensata per i modelli linguistici. Prima che qualcosa torni a te, un tester AI segue i passaggi in una copia dell'app e allega uno screenshot. Il lavoro finito arriva nella tua pila con i file modificati e il diff. Tu lo accetti, oppure lasci un commento e il team si sveglia e riprova. Solo tu puoi spostare una card in Fatto.","Una giornata con AI-gile, più o meno. La sera lasci qualche commento: questo pulsante è nel posto sbagliato, quella lista va ordinata, potremmo avere una modalità scura. Vai a letto. Gli agenti leggono i commenti, fanno le modifiche, le testano e te le riconsegnano. Se Da fare si svuota, la guardia notturna la riempie dal backlog con card che non richiedono risposte da parte tua. La mattina trovi un'unica pila corta: un paio di domande e qualche cosa da provare, ognuna con passaggi che una persona assonnata riesce a seguire e uno screenshot che mostra come funziona. Clicchi, accetti quelle buone e rimandi indietro le altre. Un contatore di token mostra quanto è servito, e No Token Mode c'è per le settimane magre. Poi fai colazione, cosa in cui gli agenti non possono ancora aiutarti.","Prima di tutto, cosa AI-gile non è. Non è una startup, non è in vendita e nessuno raccoglie i tuoi dati. È una board gratuita che gira sul tuo computer, senza account, senza tracker e senza cookie. Cos'è invece: un posto ordinato dove vedere tutti i progetti di programmazione con l'AI in una volta, con un team di agenti che lavora le card e te che prendi le decisioni. Fonde le card affini, sistema i titoli confusi e controlla che il codice resti snello. Parla circa 120 lingue, dall'olandese e dal fiammingo al pirata e al klingon. Gli amici possono scriversi in privato e con cifratura. L'hanno costruita Rich e un gran numero di agenti pazienti, soprattutto usandola. È in pre-alpha chiusa, quindi in certi punti è ruvida. Se ti sembra divertente, chiedi con gentilezza e magari entri in anticipo."]}],"quips":{"1":"Una parola. Audace. Forse troppo.","3":"Tre parole. Già più oneste della maggior parte delle pagine di prodotto.","8":"Otto parole. Ancora meno di una riunione in piedi.","21":"Le lunghezze sono story point, a proposito. Ovviamente.","55":"Cinquantacinque parole. Mentre leggevi, due card sono state completate.","144":"Questa è la più lunga. Il 233 non esiste. Gli agenti sono andati a dormire."}},"timeline":{"first-idea.name":"La prima idea","first-idea.line":"La primissima conversazione, quando non esisteva ancora nessun codice.","first-board.name":"La prima board","first-board.line":"Una board che tiene traccia della propria costruzione: card, colonne, trascina e rilascia, progetti.","team-roles.name":"Team e ruoli","team-roles.line":"Profili degli agenti, modelli di team, spazi e chi fa cosa.","install.name":"Installazione e rilasci","install.line":"Uno zip che un amico può installare, aggiornamenti automatici, canali e ripristino.","usage-saver.name":"Risparmio d'uso","usage-saver.line":"Misurare quanto costano le esecuzioni, tenere il codice snello, risparmiare il limite.","friends.name":"Amici e condivisione","friends.line":"Messaggi privati, un relay cifrato, inviti, ruoli e progetti condivisi.","languages.name":"Lingue","languages.line":"Ogni testo dello schermo in un file di lingua, con olandese e fiammingo per primi.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester controlla prima ogni consegna e mostra cosa ha visto.","website.name":"Il sito web","website.line":"aigile.lol, il teaser e questa cronologia.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modalità streamer, GIF ed emoji.","no-ai.name":"Edizione senza AI","no-ai.line":"Una board per chi programma senza AI, e board pubbliche.","night-watch.name":"Guardia notturna","night-watch.line":"Un guardiano e uno Scrum Master tengono i team sul pezzo mentre dormi.","p-more.name":"Tutto il resto","p-more.line":"Idee più piccole che aspettano ancora il loro turno.","p-android.name":"Telefono e Android","p-android.line":"Raggiungi la tua board dal telefono, poi con un'app Android nativa.","p-release.name":"Alpha e oltre","p-release.line":"Alpha chiusa, il sito online, poi la beta.","p-languages.name":"Più lingue","p-languages.line":"130 lingue, e una modalità immersione per chi impara.","p-engines.name":"Più motori AI","p-engines.line":"Scegli Claude, Codex, Gemini, Copilot o Cursor per ogni agente.","p-pro.name":"Pratica professionale","p-pro.line":"Etichette di rischio, blocchi di merge, card di incidente e protezioni.","p-self.name":"Prendersi cura di te","p-self.line":"Modalità stanco, promemoria di cura di sé e le 4:20.","p-servers.name":"Server e crescita","p-servers.line":"Impostazioni globali dei server, ruoli e pianificazione della crescita.","p-livestream.name":"Extra per lo streaming","p-livestream.line":"Chat di Twitch, emoji personalizzate e una vista live pubblica."},"words":{"button":"📖 Gergo tecnico","h":"📖 Parole spiegate","intro":"Le parole che incontri in AI-gile, in parole semplici: costruire, cambiare in sicurezza, tenere tutto in funzione per chi lo usa e lavorare in team con l'IA.","search":"Cerca una parola…","none":"Nessuna parola corrisponde.","close":"Chiudi","count":{"one":"{count} parola","other":"{count} parole"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Costruire"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Cambiare in sicurezza"},{"id":"run","name":"🛎️ Gestire un servizio"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Idee e lavoro non ancora pianificati. Finché non passano in Da fare, nessuno ci lavora."},{"id":"sprint","g":"agile","word":"Sprint","text":"Un breve periodo di lavoro (spesso una o due settimane) con un insieme concordato di card da finire.","also":["sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un rapido punto della situazione: cosa ha fatto ogni membro del team, cosa fa dopo e cosa lo blocca.","also":["standup","stand up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Una board con colonne (Da fare, In corso, Fatto) in cui le card si spostano da sinistra a destra mentre si lavora."},{"id":"wip","g":"agile","word":"Limite WIP","text":"Work in progress: il massimo di card che una colonna dovrebbe contenere, così il team finisce le cose prima di iniziarne altre.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"La breve checklist del team su cosa vuol dire «finito», per esempio testato e spiegato, prima che una card ti venga consegnata. La sua gemella, la Definition of Ready, dice quando una card è abbastanza chiara per iniziare.","also":["Definition of Ready"]},{"id":"retro","g":"agile","word":"Retrospettiva","text":"Uno sguardo indietro su come lavora il team, per concordare una cosa da fare meglio. In AI-gile una retrospettiva propone una modifica al modo di lavorare del team, e tu dici Via o Non ancora.","also":["retrospettive","retro"]},{"id":"swarm","g":"agile","word":"Sciame","text":"Tutti all'opera: ogni team lascia il resto per aiutare su un progetto urgente finché non è risolto. Gli altri progetti nel frattempo aspettano.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Chi tiene il lavoro in movimento: nota le card bloccate, dà una spinta ai team e ti ricorda cosa ti aspetta. In AI-gile il Lead Scrum Master lo fa su tutti i progetti.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"La cartella del progetto con il codice e tutta la cronologia dei commit, di solito tenuta anche su GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una linea di lavoro separata nel codice, così si possono fare modifiche senza toccare la versione principale.","also":["Branch"]},{"id":"commit","g":"build","word":"Commit","text":"Un'istantanea salvata del codice, con una breve nota su cosa è cambiato. Puoi sempre tornare a una di esse.","also":["commit"]},{"id":"push","g":"build","word":"Push","text":"Inviare le istantanee salvate (commit) da questo computer a GitHub, così sono al sicuro e condivise."},{"id":"merge","g":"build","word":"Merge","text":"Unire le modifiche di un branch alla versione principale."},{"id":"pr","g":"build","word":"Pull request","text":"Chiedere che le modifiche di un branch vengano controllate e unite alla versione principale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"Riordinare il codice senza cambiare ciò che fa: file più piccoli, nomi più chiari, meno ripetizioni."},{"id":"bug","g":"build","word":"Bug","text":"Qualcosa che non funziona come dovrebbe.","also":["Bug"]},{"id":"peerreview","g":"build","word":"Revisione tra pari","text":"Un secondo paio d'occhi: un'altra IA controlla il lavoro di ogni card prima che arrivi a te, così passano meno errori.","also":["peer review","code review","revisione del codice"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Provare un lavoro finito per verificare che faccia ciò che era stato chiesto, prima di accettarlo.","also":["testare","testi"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Sta per quality assurance, cioè garanzia di qualità: i controlli automatici che girano prima che qualcosa vada online. Quando la QA è rossa, qualcosa non è passato, e non può andare online finché non viene sistemato.","also":["controlli di qualità","controllo qualità"]},{"id":"testpile","g":"test","word":"Pila di test","text":"Le card finite che aspettano di essere provate da te, una dopo l'altra. Accettane una o rimandala indietro con una nota, e arriva la successiva.","also":["pile di test"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Mettere online una nuova versione, per esempio su un server dove la usano le persone."},{"id":"release","g":"change","word":"Rilascio","text":"Un insieme di lavoro finito, con un nome, che va online tutto insieme, con brevi note su cosa è cambiato. 🚀 Rilasci scrive le note partendo dalle card completate.","also":["rilasci","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Tornare all'ultima versione che funzionava quando una nuova crea problemi. In AI-gile prepara una checklist con i passaggi per annullare scritti su ogni modifica.","also":["torna indietro","tornare indietro","roll back"]},{"id":"live","g":"change","word":"Online","text":"La versione vera che usano le persone, a differenza di una copia per fare prove. Gli sviluppatori la chiamano anche produzione.","also":["produzione","in produzione"],"noTip":1},{"id":"change","g":"change","word":"Modifica","text":"Una modifica pianificata a qualcosa su cui le persone contano, messa per iscritto prima: cosa, perché, il rischio, quando e come annullarla. Iniziane una con 🔀 Proponi una modifica.","also":["richiesta di modifica","richieste di modifica"],"noTip":1},{"id":"risk","g":"change","word":"Rischio","text":"Qualcosa che potrebbe andare storto, valutato in base a quanto è probabile e quanto sarebbe grave. ⚠️ Rischi li tiene in un'unica lista, dal punteggio più alto, ognuno con una data per riguardarlo.","also":["rischi","registro dei rischi"]},{"id":"chgwin","g":"change","word":"Finestra di modifica","text":"I momenti in cui le modifiche possono andare online, per esempio un tranquillo martedì sera. Fuori da una finestra una card di modifica non si può completare, a meno che non sia un'emergenza.","also":["finestre di modifica"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Un voto rapido subito prima che una modifica vada online: ogni persona che deve approvare dice Via libera o Stop. Si procede solo se sono tutti d'accordo.","also":["go/no go","go-no-go","via libera"]},{"id":"approval","g":"change","word":"Approvazione","text":"Aspettare un sì prima che il lavoro inizi. Una card proposta da un amico, o una modifica, aspetta in ✅ Approvazioni finché non la approvi o la rifiuti.","also":["approvazioni"]},{"id":"quiettime","g":"change","word":"Orario di silenzio","text":"Un periodo, come una diretta, una demo o la notte, in cui niente va online. I team continuano a lavorare e a testare, ma la messa online aspetta che finisca. Altrove si chiama change freeze (congelamento delle modifiche).","also":["orari di silenzio","change freeze","congelamento delle modifiche"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Servizio","text":"Qualcosa che hai costruito e su cui le persone contano, come un sito o un'app, curato perché continui a funzionare. Spunta «Questo progetto è un servizio» e indica cosa offre, chi lo usa e chi è reperibile.","also":["servizi"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Controllo di uptime","text":"Un controllo automatico, ogni pochi minuti, che il tuo servizio risponda ancora. Se fallisce più volte di fila, AI-gile apre da solo una card di incidente.","also":["uptime","controlli di uptime"]},{"id":"statuspage","g":"run","word":"Pagina di stato","text":"Una pagina pubblica che mostra se un servizio funziona (verde, arancione o rosso) con l'ultimo aggiornamento, così chi lo usa può controllare invece di chiedere.","also":["pagine di stato","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Il punto in cui arrivano le domande e le segnalazioni di chi usa il tuo servizio. AI-gile smista ognuna in richiesta, incidente o idea, e lo dice quando somiglia a qualcosa già segnalato.","also":["help desk","helpdesk","assistenza"]},{"id":"svcrequest","g":"run","word":"Richiesta di servizio","text":"Qualcuno che chiede una cosa normale, come un nuovo account o un piccolo aiuto, invece di segnalare che qualcosa è rotto. Aspetta il suo turno: un incidente passa prima.","also":["richieste di servizio"]},{"id":"incident","g":"run","word":"Incidente","text":"Qualcosa che in questo momento non funziona per chi lo usa, come il sito che non risponde. Una card 🔥 incidente salta la coda: farlo funzionare di nuovo viene prima di tutto.","also":["incidenti"]},{"id":"major","g":"run","word":"Incidente grave","text":"Un incidente grosso: molte persone coinvolte, oppure soldi o dati a rischio. Un solo pulsante mette tutti i team al lavoro (sciame), sveglia chi è reperibile e chiede un aggiornamento di stato ogni 30 minuti.","also":["incidenti gravi"]},{"id":"oncall","g":"run","word":"Reperibilità","text":"Essere chi risponde quando qualcosa si rompe, anche di notte. Ogni servizio ha un membro del team reperibile, che viene svegliato per primo per i suoi incidenti.","also":["reperibile","reperibili","di guardia","on call"]},{"id":"replyby","g":"run","word":"Orario di risposta","text":"Quanto può aspettare una card prima di ricevere una prima risposta, per esempio un'ora per un incidente. Dopo compare un orologio rosso, così niente viene dimenticato in silenzio. Si chiama anche obiettivo di risposta.","also":["orari di risposta","obiettivo di risposta","obiettivi di risposta"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un breve sguardo indietro dopo un incidente: cosa è successo, cosa ha aiutato e cosa cambiare, senza dare la colpa a nessuno. Un incidente non si può chiudere senza.","also":["postmortem","revisione post-incidente"]},{"id":"problem","g":"run","word":"Problema","text":"La causa nascosta dietro uno o più incidenti. Una card 🧩 problema raggruppa gli incidenti che continuano a tornare, così la causa viene trovata e risolta una volta per tutte.","also":["problemi"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa radice","text":"Il vero motivo per cui qualcosa si è rotto, non solo quello che hai visto andare storto. Risolvi la causa radice e l'incidente smette di tornare.","also":["cause radice","causa principale"]},{"id":"workaround","g":"run","word":"Soluzione temporanea","text":"Un modo per far funzionare le cose finché la vera correzione non è pronta, come riavviare qualcosa quando si blocca. Viene scritta sulla card del problema, così nessuno deve scoprirla di nuovo.","also":["soluzioni temporanee","workaround"]},{"id":"knownerror","g":"run","word":"Errore noto","text":"Un problema di cui si conosce la causa e che ha una soluzione temporanea, ma non è ancora risolto. 🧩 Errori noti li elenca, così tutti usano la soluzione temporanea invece di rimettersi a scavare.","also":["errori noti"]},{"id":"runbook","g":"run","word":"Runbook","text":"Istruzioni passo passo per risolvere un tipo di guaio già noto, così si fa sempre allo stesso modo, in fretta. Dopo un incidente grosso il team può proportene uno da approvare con un OK.","also":["manuale operativo","manuali operativi"]},{"id":"ci","g":"run","word":"Elemento di configurazione","text":"Una cosa da cui dipende il tuo servizio, come un server, un dominio, un certificato, una chiave o un fornitore. 🗂️ Elementi li elenca per servizio, così vedi cosa colpisce un incidente e cosa va rinnovato o ha bisogno di un backup.","also":["elementi di configurazione"]},{"id":"expiry","g":"run","word":"Scadenza","text":"AI-gile tiene d'occhio date come quella in cui scade un certificato o un dominio. Nei 30 giorni prima della data crea una card per rinnovarlo, così niente smette di funzionare all'improvviso.","also":["scadenze","data di scadenza","date di scadenza","controllo delle scadenze"]},{"id":"backup","g":"run","word":"Backup","text":"Una copia salvata dei tuoi dati di prima, a cui ricorrere se qualcosa va perso o si danneggia. AI-gile fa ogni giorno un backup delle tue board.","also":["copia di sicurezza","copie di sicurezza"]},{"id":"restore","g":"run","word":"Ripristino","text":"Rimettere i dati da un backup. Un backup conta davvero solo quando sai che si può ripristinare, quindi vale la pena provarlo ogni tanto.","also":["ripristinare","ripristinato","ripristinata"]},{"id":"svcreview","g":"run","word":"Revisione del servizio","text":"Uno sguardo indietro su un mese di un servizio: incidenti aperti e risolti, quanto in fretta le persone hanno avuto una risposta, uptime e token usati. La Revisione mensile lo mostra per ogni servizio.","also":["revisioni del servizio","revisione mensile","revisioni mensili"]},{"id":"accessreview","g":"run","word":"Revisione accessi","text":"Controllare ogni 90 giorni chi può ancora entrare: link di condivisione, ruoli degli amici e segreti conservati. Mantieni o rimuovi ciascuno, così i vecchi accessi non restano in giro.","also":["revisioni accessi","revisione degli accessi"]},{"id":"improvements","g":"run","word":"Elenco dei miglioramenti","text":"Tutto ciò in cui il team ha deciso di migliorare, in un unico posto: suggerimenti delle retrospettive, azioni delle revisioni e correzioni dei problemi, ognuno con il suo stato. Lo trovi sotto 📈 Miglioramenti.","also":["elenchi dei miglioramenti","miglioramenti"]},{"id":"tokencap","g":"run","word":"Limite di token","text":"Un limite mensile ai token che gli agenti di un servizio possono usare. All'80% ricevi un avviso; al 100% il loro lavoro in background aspetta il mese dopo, o finché non alzi il limite.","also":["limiti di token","limite mensile di token"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Un'IA che lavora da sola su un compito: legge il codice, fa modifiche, esegue controlli e riferisce.","also":["agenti"]},{"id":"token","g":"ai","word":"Token","text":"L'unità in cui si conta l'uso dell'IA: più o meno qualche lettera di testo letto o scritto. Meno token, più piano ti resta.","also":["Token"]},{"id":"hook","g":"ai","word":"Hook","text":"Un piccolo comando che parte da solo in un momento preciso, per esempio all'avvio di una sessione IA, così il team sente i tuoi commenti.","also":["Hook"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
